/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { normalizeReference, resolveReference, UriError } from './uri.js'

/** Splits stdin into records, dropping the empty tail a trailing newline leaves. */
function splitRecords(input) {
  if (input === '') return []
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || (mode !== 'normalize' && mode !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const input = readFileSync(0, 'utf8')
  const records = splitRecords(input)
  const outputs = []

  for (let i = 0; i < records.length; i++) {
    const lineNum = i + 1
    const record = records[i]
    try {
      if (mode === 'normalize') {
        outputs.push(normalizeReference(record, lineNum))
      } else {
        const spaceIdx = record.indexOf(' ')
        if (spaceIdx === -1) {
          throw new UriError(`line ${lineNum}: expected a base and a reference`)
        }
        outputs.push(resolveReference(record.slice(0, spaceIdx), record.slice(spaceIdx + 1), lineNum))
      }
    } catch (err) {
      if (err instanceof UriError) {
        process.stderr.write(`error: ${err.message}\n`)
        process.exit(2)
      }
      throw err
    }
  }

  process.stdout.write(outputs.map((line) => line + '\n').join(''))
}

main()
"}

