import("./src/uri.js").then(({normalizeReference, resolveReference, UriError}) => {
  function tryN(input) {
    try { return normalizeReference(input, 1); } catch(e) { return "ERR: " + e.message; }
  }
  console.log(tryN("http://a@b@host:1234/x"));
  console.log(tryN("http://[::1]:8080/x"));
  console.log(tryN("http://[::1]/x"));
  console.log(tryN("http://a:abc/x"));
  console.log(tryN("http://a/%")); // truncated in path
  console.log(tryN("http://us%er@a/x")); // truncated in userinfo? %er not valid hex -> error userinfo
  console.log(tryN("http://a%zz/x")); // truncated host
  console.log(tryN("http://a/x?%1")); // truncated query
  console.log(tryN("http://a/x#%1")); // truncated fragment
  console.log(tryN("mailto:foo@bar.com"));
  console.log(tryN("")); // empty ref -> path empty, no scheme no authority -> just ""
  console.log(tryN("#frag"));
  console.log(tryN("?q="));
});
' 2>&1
","description":"Test edge cases for authority parsing and errors"}

